  "}",
  "function sourcesPanel(){",
  " if(!commitDraft())return;unsaved=false;E.sel=null;$('#advanced').open=false;",
  " $('#painel').innerHTML=detailsHeader('Sobre o levantamento')+`<h2>Um mapa para construir juntos</h2><p class=\"detail-lead\">Escolha uma área à esquerda. Depois, abra uma atividade e conte o que está claro, o que gera dúvida ou o que precisa mudar.</p><div class=\"notice blue\">As descrições são um ponto de partida. Conferir o entendimento não equivale a aprovar uma rotina institucional.</div>`+disclosure('Documentos que apoiaram este mapa',D.sources.map(f=>`<article class=\"source-card\"><b>${esc(f.title)}</b><small>${esc(f.detail)}</small></article>`).join(''))+`<p class=\"review-note\">Documentos completos e anexos internos dependem da autorização da coordenação.</p>`;showDetails();highlight();",
  "}",
  "function renderMatrix(){",
  " const host=$('#tabela');if(E.view==='validacao'){",
