  " }",
  " host.innerHTML=`<div class=\"tabs-caption\"><b>${scopeActs().length} atividades do levantamento ${E.scope?'· '+E.scope:''}</b><span class=\"small\">Clique no ID para abrir detalhes</span></div><table class=\"mx\" aria-label=\"${E.view==='validacao'?'Matriz de validação':'Matriz de atividades'}\"><thead><tr><th class=\"idcol\">ID</th><th>Subprocesso e atividade</th><th>Entendimento coletado</th><th>Áreas / responsável</th><th>Sistemas e registros</th><th>Ponto a validar</th><th>Situação do levantamento</th></tr></thead><tbody>${scopeActs().filter(a=>!E.search||norm(JSON.stringify(a)).includes(norm(E.search))).map(a=>`<tr><td class=\"idcol\"><button class=\"link\" data-node=\"${a.id}\">${a.id}</button><div class=\"small\">${esc(MAC[a.macro].title)}</div></td><td class=\"textcell\"><span class=\"small\">${esc(a.subprocess)}</span><br><b><button class=\"link\" data-node=\"${a.id}\">${esc(a.title)}</button></b></td><td class=\"textcell\">${esc(a.account)}</td><td>${esc(a.area)}<div class=\"fonte\">Responsável: ${esc(REV[a.id]?.owner||a.owner)}</div></td><td>${esc(a.records)}</td><td class=\"textcell\">${esc(a.question)}<div class=\"fonte\">${esc(a.source)}</div></td><td><span class=\"status-label\">${statusSvg(reviewStatus(a.id))}${STATUS[reviewStatus(a.id)].name}</span></td></tr>`).join('')}</tbody></table>`;",
  "}",
  "function renderTable(){",
  " if(['matriz','validacao'].includes(E.view))return renderMatrix();",
  " const host=$('#tabela');if(E.view==='perguntas'){",
