  " $('#walkbar').classList.toggle('active',E.walk);if(E.walk){$('#walklabel').textContent=`Atividade ${E.step+1} de ${scopeActs().length}`;$('#prev').disabled=E.step===0;$('#next').disabled=E.step===scopeActs().length-1;}",
  "}",
  "function render(){sidebar();progress();controls();G=buildGraph();placeGraph();drawGraph(true);if(E.view!=='grafo')renderTable();if(E.sel&&NODES[E.sel])panelNode(E.sel);else panelSummary();search();}",
