  " if(E.view!=='grafo'){renderTable();if(!$('#tabela').querySelector('.activity-card,tbody tr'))$('#tabela').insertAdjacentHTML('beforeend','<p class=\"notice\" role=\"status\">Nenhum item encontrado. Limpe a busca para ver todos os itens deste processo.</p>');}",
